/**
 * The Gamma-Exponential conjugate model for latency and cost.
 *
 * A latency or cost observation `x > 0` is modeled as `x ~ Exponential(lambda)`. The rate `lambda`
 * carries a Gamma(shape, rate) posterior; the conjugate update adds one to `shape` and the observed
 * value to `rate`, so inference is closed form and online. The quantity a router cares about is the
 * expected value of the Exponential, the mean latency or mean cost, which is `1 / lambda`. Its
 * posterior is Inverse-Gamma(shape, rate) with mean `rate / (shape - 1)` for `shape > 1`. Thompson
 * sampling draws `lambda` from the Gamma posterior and returns `1 / lambda`. Nothing here approximates;
 * the credible interval is the exact Gamma quantile.
 *
 * @packageDocumentation
 */

import { BayesRouteError } from '../errors.js';
import { gammaQuantile } from '../mathspecial.js';
import { type Rng, sampleGammaRate } from '../rng.js';
import type { CredibleInterval, GammaPosterior } from '../types.js';

export type { CredibleInterval, GammaPosterior, GammaPrior } from '../types.js';

/** Default mass for a credible interval. */
export const DEFAULT_CREDIBLE_LEVEL = 0.95;

/** Throw unless `p` is a valid Gamma posterior (both parameters finite and positive). */
export function assertGammaPosterior(p: GammaPosterior): void {
  if (!Number.isFinite(p.shape) || p.shape <= 0 || !Number.isFinite(p.rate) || p.rate <= 0) {
    throw new BayesRouteError(
      'ERR_INVALID_PRIOR',
      `Gamma requires shape > 0 and rate > 0, received shape=${p.shape} rate=${p.rate}`,
    );
  }
}

/**
 * Build a weakly-informative Gamma prior whose expected value (mean latency or mean cost) equals
 * `meanValue`. The `strength` is the prior pseudo-count and must exceed 1 so the inverse-gamma mean is
 * finite; a small value such as 2 keeps the prior weak and quick to adapt.
 */
export function gammaPriorFromMean(meanValue: number, strength = 2): GammaPosterior {
  if (!Number.isFinite(meanValue) || meanValue <= 0) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `gammaPriorFromMean requires meanValue > 0, received ${meanValue}`,
    );
  }
  if (!Number.isFinite(strength) || strength <= 1) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `gammaPriorFromMean requires strength > 1, received ${strength}`,
    );
  }
  return { shape: strength, rate: meanValue * (strength - 1) };
}

/** Posterior mean of the Exponential rate `lambda`, `shape / rate`. */
export function rateMean(p: GammaPosterior): number {
  return p.shape / p.rate;
}

/**
 * Posterior mean of the expected value (mean latency or mean cost), `rate / (shape - 1)`. Returns
 * positive infinity when `shape <= 1`, where the inverse-gamma mean is undefined.
 */
export function expectedValueMean(p: GammaPosterior): number {
  if (p.shape <= 1) {
    return Number.POSITIVE_INFINITY;
  }
  return p.rate / (p.shape - 1);
}

/** Conjugate update: fold one observed latency or cost value into the posterior. */
export function updateValue(p: GammaPosterior, value: number): GammaPosterior {
  assertGammaPosterior(p);
  if (!Number.isFinite(value) || value <= 0) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `Gamma update requires a positive observed value, received ${value}`,
    );
  }
  return { shape: p.shape + 1, rate: p.rate + value };
}

/** Conjugate update: fold a batch of `count` observations whose values sum to `sum`. */
export function updateBatch(p: GammaPosterior, count: number, sum: number): GammaPosterior {
  assertGammaPosterior(p);
  if (!Number.isFinite(count) || count < 0 || !Number.isFinite(sum) || sum < 0) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `Gamma updateBatch requires non-negative finite count and sum, received count=${count} sum=${sum}`,
    );
  }
  return { shape: p.shape + count, rate: p.rate + sum };
}

/** Draw a rate `lambda` from the Gamma posterior using the given seeded source. */
export function sampleRate(p: GammaPosterior, rng: Rng): number {
  assertGammaPosterior(p);
  return sampleGammaRate(p.shape, p.rate, rng);
}

/**
 * Draw an expected value (mean latency or mean cost) from the posterior, `1 / lambda`, where `lambda`
 * is a Gamma draw. This is the Thompson-sampling draw for latency and cost.
 */
export function sampleValue(p: GammaPosterior, rng: Rng): number {
  return 1 / sampleRate(p, rng);
}

/**
 * Equal-tailed credible interval over the expected value (mean latency or mean cost). Because the
 * value is `1 / lambda`, the lower value bound comes from the upper rate quantile and vice versa.
 */
export function valueCredibleInterval(
  p: GammaPosterior,
  level: number = DEFAULT_CREDIBLE_LEVEL,
): CredibleInterval {
  assertGammaPosterior(p);
  if (!Number.isFinite(level) || level <= 0 || level >= 1) {
    throw new BayesRouteError(
      'ERR_INVALID_INPUT',
      `credible level must be in (0, 1), received ${level}`,
    );
  }
  const tail = (1 - level) / 2;
  // Rate quantiles: Gamma(shape, rate) quantile is the standard Gamma(shape, 1) quantile over rate.
  const rateLow = gammaQuantile(tail, p.shape) / p.rate;
  const rateHigh = gammaQuantile(1 - tail, p.shape) / p.rate;
  return {
    lower: 1 / rateHigh,
    upper: 1 / rateLow,
    level,
  };
}
